package com.transportlogistics.app.freight.manifest.adapters.transaction;
import com.transportlogistics.app.freight.manifest.ports.outbound.CargoManifestTransaction;import com.transportlogistics.app.shared.domain.ConflictException;import org.springframework.dao.ConcurrencyFailureException;import org.springframework.stereotype.Component;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import java.util.function.Supplier;
@Component class SpringCargoManifestTransaction implements CargoManifestTransaction {private final TransactionTemplate tx;SpringCargoManifestTransaction(PlatformTransactionManager manager){tx=new TransactionTemplate(manager);}public <T>T execute(Supplier<T> operation){try{return tx.execute(status->operation.get());}catch(ConcurrencyFailureException ex){throw new ConflictException("CARGO_MANIFEST_CONCURRENT_UPDATE","Cargo manifest changed concurrently; reload and retry",ex);}}}
